[[{"sha":"cb56967d666f252de25cbe922b7b2281a31bc0e2","filename":"math-tool.Tests.ps1","status":"added","additions":94,"deletions":0,"changes":94,"blob_url":"https://github.com/edburns/dd-3061974-01-bash/blob/c49968473205caf2bd11718182a9c4cdd39a1948/math-tool.Tests.ps1","raw_url":"https://github.com/edburns/dd-3061974-01-bash/raw/c49968473205caf2bd11718182a9c4cdd39a1948/math-tool.Tests.ps1","contents_url":"https://api.github.com/repos/edburns/dd-3061974-01-bash/contents/math-tool.Tests.ps1?ref=c49968473205caf2bd11718182a9c4cdd39a1948","patch":"@@ -0,0 +1,94 @@
+Set-StrictMode -Version Latest
+$ErrorActionPreference = 'Stop'
+
+Describe 'Get-Fibonacci unit behavior' {
+    BeforeAll {
+        $scriptPath = Join-Path $PSScriptRoot 'math-tool.ps1'
+        $dotSourceOutput = . $scriptPath -N 0
+    }
+
+    It 'does not emit output when dot-sourced' {
+        $dotSourceOutput | Should -BeNullOrEmpty
+    }
+
+    It 'returns 0 for N=0' {
+        Get-Fibonacci -N 0 | Should -Be 0
+    }
+
+    It 'returns 1 for N=1' {
+        Get-Fibonacci -N 1 | Should -Be 1
+    }
+
+    It 'returns 5 for N=5' {
+        Get-Fibonacci -N 5 | Should -Be 5
+    }
+
+    It 'rejects negative input' {
+        { Get-Fibonacci -N -1 } | Should -Throw
+    }
+}
+
+Describe 'math-tool CLI behavior' {
+    BeforeAll {
+        $scriptPath = Join-Path $PSScriptRoot 'math-tool.ps1'
+        $invokeChildPwsh = {
+            param(
+                [Parameter(Mandatory = $true)]
+                [string[]]$Arguments
+            )
+
+            $stdoutPath = [System.IO.Path]::GetTempFileName()
+            $stderrPath = [System.IO.Path]::GetTempFileName()
+
+            try {
+                $process = Start-Process -FilePath 'pwsh' -ArgumentList $Arguments -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath
+
+                [PSCustomObject]@{
+                    ExitCode = $process.ExitCode
+                    StdOut   = @(Get-Content -Path $stdoutPath)
+                    StdErr   = Get-Content -Path $stderrPath -Raw
+                }
+            }
+            finally {
+                Remove-Item -LiteralPath $stdoutPath, $stderrPath -ErrorAction SilentlyContinue
+            }
+        }
+    }
+
+    It 'prints exactly one line for N=0' {
+        $result = & $invokeChildPwsh -Arguments @('-NoLogo', '-NoProfile', '-File', $scriptPath, '-N', '0')
+
+        $result.ExitCode | Should -Be 0
+        $result.StdErr | Should -BeNullOrEmpty
+        $result.StdOut.Count | Should -Be 1
+        $result.StdOut[0] | Should -Be 'Fibonacci(0) = 0'
+    }
+
+    It 'prints exactly one line for N=1' {
+        $result = & $invokeChildPwsh -Arguments @('-NoLogo', '-NoProfile', '-File', $scriptPath, '-N', '1')
+
+        $result.ExitCode | Should -Be 0
+        $result.StdErr | Should -BeNullOrEmpty
+        $result.StdOut.Count | Should -Be 1
+        $result.StdOut[0] | Should -Be 'Fibonacci(1) = 1'
+    }
+
+    It 'prints exactly one line for N=5' {
+        $result = & $invokeChildPwsh -Arguments @('-NoLogo', '-NoProfile', '-File', $scriptPath, '-N', '5')
+
+        $result.ExitCode | Should -Be 0
+        $result.StdErr | Should -BeNullOrEmpty
+        $result.StdOut.Count | Should -Be 1
+        $result.StdOut[0] | Should -Be 'Fibonacci(5) = 5'
+    }
+
+    It 'rejects negative input and does not print success-shaped output' {
+        $result = & $invokeChildPwsh -Arguments @('-NoLogo', '-NoProfile', '-File', $scriptPath, '-N', '-1')
+
+        $result.ExitCode | Should -Not -Be 0
+        $result.StdOut.Count | Should -BeLessOrEqual 1
+        if ($result.StdOut.Count -eq 1) {
+            $result.StdOut[0] | Should -Not -Match '^Fibonacci\(-1\) = \d+$'
+        }
+    }
+}"},{"sha":"cdd092d6d2378d7b72cd8b2627b150b87232df73","filename":"math-tool.ps1","status":"added","additions":38,"deletions":0,"changes":38,"blob_url":"https://github.com/edburns/dd-3061974-01-bash/blob/c49968473205caf2bd11718182a9c4cdd39a1948/math-tool.ps1","raw_url":"https://github.com/edburns/dd-3061974-01-bash/raw/c49968473205caf2bd11718182a9c4cdd39a1948/math-tool.ps1","contents_url":"https://api.github.com/repos/edburns/dd-3061974-01-bash/contents/math-tool.ps1?ref=c49968473205caf2bd11718182a9c4cdd39a1948","patch":"@@ -0,0 +1,38 @@
+[CmdletBinding()]
+param(
+    [Parameter(Mandatory = $true)]
+    [ValidateRange(0, [int]::MaxValue)]
+    [int]$N
+)
+
+Set-StrictMode -Version Latest
+$ErrorActionPreference = 'Stop'
+
+function Get-Fibonacci {
+    [CmdletBinding()]
+    param(
+        [Parameter(Mandatory = $true)]
+        [ValidateRange(0, [int]::MaxValue)]
+        [int]$N
+    )
+
+    if ($N -lt 2) {
+        return $N
+    }
+
+    $previous = 0
+    $current = 1
+
+    for ($i = 2; $i -le $N; $i++) {
+        $next = $previous + $current
+        $previous = $current
+        $current = $next
+    }
+
+    return $current
+}
+
+if ($MyInvocation.InvocationName -ne '.') {
+    $value = Get-Fibonacci -N $N
+    Write-Output "Fibonacci($N) = $value"
+}"}]]
